import {initialState,TODAY} from './store.js';
import {equipmentLabels,exercises,anatomySources} from './data.js';
import {esc,btn,empty,field,select,num,modal,toast} from './ui.js';
import {createVault,decryptState,encryptState} from './vault.js';
import {validateState} from './validation.js';
export function settingsView(C){const p=C.state.profile;return `<div class="page-head"><div><h1>Settings</h1></div>${C.vault?btn('Lock journal','lock-journal','','lock'):''}</div><div class="grid two"><section class="card"><h2>Profile</h2><form id="profile-form"><div class="form-grid">${field('name','Name · optional',p.name,'text','maxlength="100"')}${select('units','Display units',p.units,[['metric','Metric · kg / cm'],['imperial','Imperial · lb / in']])}${field('age','Age (years) · optional',p.age,'number','min="18" max="100" step="1"')}${field('height','Height ('+C.lengthUnit()+') · optional',C.displayLength(p.height),'number','min="1" max="300" step="any"')}${field('weight','Starting weight ('+C.weightUnit()+') · optional',C.displayWeight(p.weight),'number','min="1" max="1000" step="any"')}${select('sex','Published RMR equation coefficient',p.sex,[['','No estimate'],['male','Male coefficient (+5)'],['female','Female coefficient (−161)']],'This is a published model input, not gender identity. The model does not establish coefficient selection for every physiology.')}${select('activity','Typical activity factor · heuristic',String(p.activity),[['1.2','1.2 · Mostly sedentary'],['1.4','1.4 · Lightly active'],['1.6','1.6 · Moderately active'],['1.8','1.8 · Very active'],['2','2.0 · Extremely active']],'Includes typical exercise. Factors are rough assumptions, not validated individual measurements.')}${field('measuredTdee','Known maintenance estimate (kcal/day)',p.measuredTdee,'number','min="500" max="10000" step="1"','Overrides the activity-factor estimate; leave blank to use the equation.')}${select('goal','Primary goal',p.goal,[['maintenance','Weight maintenance'],['fat-loss','Fat loss'],['muscle-growth','Muscle growth / weight gain'],['strength','Strength'],['endurance','Endurance'],['general','General fitness'],['recomposition','Body recomposition'],['mobility','Mobility']])}${field('targetWeight','Target weight ('+C.weightUnit()+') · optional',C.displayWeight(p.targetWeight),'number','min="1" max="1000" step="any"')}${select('experience','Training experience',p.experience,[['beginner','Beginner'],['intermediate','Intermediate'],['advanced','Advanced']])}${field('days','Available training days per week',p.days,'number','required min="1" max="7" step="1"')}${field('hrmax','Known maximum heart rate (bpm) · optional',p.hrmax,'number','min="80" max="250" step="1"')}${field('activityGoal','Weekly moderate-equivalent goal (minutes)',p.activityGoal,'number','required min="30" max="1000" step="1"')}${field('recoveryHours','Atlas recent-training window (hours)',p.recoveryHours,'number','required min="24" max="168" step="1"','Timing overlay only. This is not a measured recovery duration.')}</div><fieldset style="border:0;padding:0;margin:18px 0"><legend style="font-size:.875rem;font-weight:600;margin-bottom:14px">Available equipment</legend><div class="form-grid">${Object.entries(equipmentLabels).map(([id,label])=>`<label class="check"><input type="checkbox" name="equipment" value="${id}" ${p.equipment.includes(id)?'checked':''}>${label}</label>`).join('')}</div></fieldset>${field('limitations','Preferences / limitations · optional',p.limitations,'text','maxlength="1000"','The local planner displays these notes but does not interpret injuries or medical restrictions.')}<label class="check"><input type="checkbox" name="trackWellbeing" ${p.trackWellbeing?'checked':''}>Show sleep, steps, and recovery logs</label><div class="modal-footer"><button type="submit" class="btn primary">Save preferences</button></div><details class="fine"><summary>About this</summary><p>Energy equations are intended for generally healthy adults. This app only calculates Mifflin–St Jeor within the original study’s age range of 19–78; it does not extrapolate to children, pregnancy or illness. ${C.sourceLinks(['mifflin1990'])}</p></details><p class="error" role="alert"></p></form></section><div class="stack"><section class="card"><h2>Storage and lock</h2><div class="row"><span>Storage</span><strong>On this device</strong></div><div class="row"><span>Passphrase lock</span><strong>${C.vault?'Enabled':'Not enabled'}</strong></div><div class="row"><span>Last full backup</span><strong>${C.prefs.lastBackup||'Never on this device'}</strong></div><div class="row"><span>Browser eviction protection</span><strong>${C.persisted===true?'On':C.persisted===false?'Not granted yet':'Unavailable'}</strong></div><div class="row"><span>Approximate record size</span><strong>${num(JSON.stringify(C.state).length/1024,1)} KB</strong></div><p class="note-box">The hosted app is private. Personal records are not uploaded to the server. Browser storage can be cleared or lost; a downloaded backup is the recovery path.</p>${C.vault?`<div class="button-group">${btn('Lock now','lock-journal')}${btn('Change passphrase','change-passphrase')}${btn('Remove lock','remove-lock')}</div>`:btn('Enable passphrase lock','enable-lock','','lock')}<details class="fine"><summary>About this</summary><p>The optional vault encrypts the journal and photos at rest using AES-GCM with a PBKDF2-derived key. It protects locked data on this device; it cannot protect an unlocked browser session. There is no passphrase reset service.</p></details></section><section class="card"><h2>Backup</h2><p class="note-box">Full backups include every record, routine, schedule and photo. ${C.vault?'Your backup will be encrypted with your journal passphrase.':'Your backup will be readable JSON containing sensitive records. Keep it somewhere private.'}</p><div class="button-group">${btn('Export full backup','export-backup','primary','download')}${btn('Restore a backup','import-backup')}</div><details class="fine"><summary>About this</summary><p>Restore validates the file before replacing records. Keep a current backup before moving to another device.</p></details><h3 class="subsection">Data exports · readable CSV</h3><div class="button-group">${[['calories','Calories'],['weights','Weight'],['sessions','Workout sets'],['cardio','Cardio']].map(([id,label])=>btn(label,'export-csv:'+id,'small')).join('')}</div><p class="meta" style="margin-top:14px">CSV exports are unencrypted, including when the journal lock is enabled.</p></section><section class="card"><h2>Offline</h2><p id="offline-state" class="note-box">${C.offlineStatus||'Preparing offline app assets…'}</p><div class="button-group">${btn('Refresh offline files','refresh-offline')}${C.installPrompt?btn('Install app','install-app'):''}</div><details class="fine"><summary>About this</summary><p>Open this app once while online to cache the app shell, library, illustrations and evidence. Core records and calculations work offline after caching. Source links require internet access. If this browser offers installation, you can add it to the home screen.</p></details></section><section class="card"><h2>About</h2><p class="note-box">${exercises.length} curated movements · 20 shared anatomical groups · 139 selectable source paths · evidence verified October 8, 2026.</p><p class="note-box">Optional wearable connections and a rotatable 3D body are not included. The app uses manual activity logging and licensed 2D illustrations.</p><div class="button-group">${btn('Take the welcome tour','start-tour','small')}${btn('Methods and sources','go-evidence','small')}</div><h3 class="subsection">Reset this device</h3>${btn('Delete all journal records','reset-journal','danger')}</section></div></div>`}
export function evidenceView(C){const filter=C.ui.evidenceQuery||'',sources=C.evidence.sources.filter(s=>(s.title+' '+s.authors+' '+s.id+' '+s.type).toLowerCase().includes(filter.toLowerCase()));return `<div class="page-head"><div><h1>Sources</h1></div><span class="badge">Verified Oct 8, 2026</span></div><section class="card" style="margin-bottom:24px"><h2>How claims are graded</h2><p class="note-box">Evidence is connected to the claim it can support. Broad training benefits have stronger support than a precise personal calorie requirement, optimal set count or recovery time. No citation is used to imply more certainty than it establishes.</p><div class="grid three"><div><h3>Established / strong</h3><p class="note-box">Anatomical functions, broad activity benefits and reviewed training principles.</p></div><div><h3>Limited / context-dependent</h3><p class="note-box">Prediction equations, specific intervention findings and individual transfer.</p></div><div><h3>App heuristic</h3><p class="note-box">Activity factors, starting routines, stability thresholds and timing overlays are disclosed product choices.</p></div></div><details class="chart-details"><summary>Read all calculation and analytics methods</summary><div class="note-box"><p><strong>Weight:</strong> A trailing 7-calendar-day mean uses only available readings. The recent slope is ordinary least squares on raw weigh-ins by actual date. At least 5 readings spanning 14 days are required. A slope is not a body-fat change measurement.</p><p><strong>Energy:</strong> Mifflin–St Jeor predicts resting expenditure; activity multipliers are heuristics. Intake-based maintenance calibration requires 24 complete days and 8 weigh-ins spanning 21 days in a 28-day window and approximately stable weight (±0.1%/week). No energy-per-kilogram conversion is used to force an estimate while weight changes.</p><p><strong>Timeline:</strong> A short-range scenario uses observed pace only for horizons up to 8 weeks. Its 50–150% pace band is illustrative and not a confidence interval. No guaranteed long-term dates are supplied.</p><p><strong>Strength:</strong> Primary working-set counts include completed, non-warm-up strength sets. Each assigned group receives one exposure; secondary sets are separate and stabilizers are excluded. Counts across groups are not additive. Frequency is distinct training dates. Load-volume is external load × repetitions and is meaningful only under consistent exercise and load conventions.</p><p><strong>1RM:</strong> Epley = load × (1 + reps/30). The app uses 2–10 repetitions and a recorded 0 RIR, or a recorded 0 RIR single. Estimates and load suggestions are suppressed for assistance, bands, bodyweight, machines, cables and timed movements. This is an estimate and does not replace testing. Progression requires two comparable sessions consistently exceeding the displayed target with effort to spare; that confirmation is an app heuristic.</p><p><strong>Cardio:</strong> Tanaka HRmax = 208 − 0.7 × age. AHA percent bands use 50–70% for moderate and 70–85% for vigorous. These sources are combined transparently, and the result does not identify ventilatory or lactate thresholds. MET gross energy ≈ MET × kg × hours; net subtracts one standardized resting MET. Energy is never automatically added to the calorie target.</p><p><strong>Composition:</strong> Estimated fat mass = weight × body-fat fraction; non-fat mass = weight − fat mass. A weigh-in within 7 days is required. Measurement-method error carries into both estimates. No photo-based estimate is made.</p><p><strong>Associations:</strong> Pearson r is computed only on paired records with at least 7 observations and nonzero variation. Missing data, sample size and confounding remain important. Correlation is not causation.</p><p><strong>Atlas:</strong> Highlights are qualitative group relationships. Source segment names do not validate fiber isolation; missing geometry is not invented. A time-since-training tint is a heuristic, not measured recovery.</p></div></details></section><div class="field"><label for="evidence-search">Search references</label><input id="evidence-search" name="evidence-query" class="search" value="${esc(filter)}" placeholder="Equation, author, guideline, topic"></div><section class="card" id="evidence-results">${sourceResults(C,sources)}</section><section class="card subsection"><h2>Asset licenses & provenance</h2><p class="note-box">Front/back anatomical geometry: “Human Anatomy Component System” by Ryan Graves, CC BY 4.0, retrieved from <a href="https://github.com/suryamolly/muscle_mapper/blob/main/CREDITS.md" target="_blank" rel="noopener">muscle_mapper’s explicit source credits</a>. The original Figma asset page was inaccessible during research; the distributing repository’s attribution is retained. Original geometry is preserved; interactive highlighting and normalized labels were added.</p><p class="note-box">Lateral plate: Hermann Braus, <em>Anatomie des Menschen</em> (1921), public domain via <a href="https://commons.wikimedia.org/wiki/File:Braus_1921_248.png" target="_blank" rel="noopener">Wikimedia Commons</a>. Point labels were added. The plate is partly dissected and ends at the upper calf.</p><p class="note-box">Exercise metadata candidate research: <a href="https://github.com/yuhonas/free-exercise-db" target="_blank" rel="noopener">free-exercise-db</a>, Unlicense. The finished library uses a focused, independently authored curriculum rather than importing hundreds of unreviewed records or photos.</p></section>`}
function sourceResults(C,sources){return sources.length?sources.map(s=>`<article class="reference" id="source-${s.id}"><div class="eyebrow">${s.year} · ${esc(s.type)}</div><h3 style="margin-top:8px">${esc(s.title)}</h3><p>${esc(s.authors.join(', '))}</p><span class="pill secondary">${esc(s.evidenceStrength)}</span><p style="margin-top:14px">${esc(s.summary)}</p><details class="chart-details"><summary>Supported claims & limitations</summary><h4>What this source supports</h4><ul>${s.supportedClaims.map(c=>`<li>${esc(c)}</li>`).join('')}</ul><h4>Limits</h4><ul>${s.limitations.map(c=>`<li>${esc(c)}</li>`).join('')}</ul></details><p style="margin-top:12px"><a href="${esc(s.url)}" target="_blank" rel="noopener">Open original source</a>${s.doi?' · DOI '+esc(s.doi):''}</p></article>`).join(''):empty('No matching references','Try an author, formula, or topic.')}
export function evidenceInput(e,C){if(e.target.name==='evidence-query'){C.ui.evidenceQuery=e.target.value;const q=e.target.value.toLowerCase();document.querySelector('#evidence-results').innerHTML=sourceResults(C,C.evidence.sources.filter(s=>(s.title+' '+s.authors+' '+s.id+' '+s.type).toLowerCase().includes(q)));return true}return false}
export function download(name,data,type='application/json'){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function lockDialog(C,change=false){modal(change?'Change your journal passphrase':'Enable journal lock',`${field('passphrase','Passphrase','', 'password','required minlength="12" autocomplete="new-password"')}${field('confirm','Confirm passphrase','', 'password','required minlength="12" autocomplete="new-password"')}<p class="notice">Save your passphrase somewhere safe. There is no recovery service. Existing backups keep their original passphrase.</p>`,async fd=>{const pass=fd.get('passphrase');if(pass!==fd.get('confirm'))throw Error('The passphrases do not match.');const vault=await createVault(pass);await C.changeVault(vault);toast('Journal encryption enabled')})}
export async function settingsAction(a,id,C){if(a==='enable-lock'||a==='change-passphrase'){lockDialog(C,a==='change-passphrase');return true}if(a==='lock-journal'){await C.lock();return true}if(a==='remove-lock'){C.confirm('Remove the local lock?','The journal will be stored without passphrase encryption on this device. Existing encrypted backups keep their passphrase.',async()=>{await C.changeVault(null);toast('Local lock removed')});return true}if(a==='export-backup'){const data=C.vault?await encryptState(C.state,C.vault):C.state;download('kinetic-backup-'+TODAY()+'.json',JSON.stringify({format:'kinetic-backup',version:1,exportedAt:new Date().toISOString(),data}));C.setPref('lastBackup',TODAY());C.render();toast('Backup downloaded');return true}if(a==='import-backup'){const d=modal('Restore a full backup',`<div class="field"><label for="backup-file">Kinetic backup file</label><input id="backup-file" name="file" type="file" accept="application/json,.json" required><small>Maximum 50 MB. Full restore replaces the records on this device.</small></div>${field('passphrase','Backup passphrase · only if encrypted','','password','autocomplete="off"')}<label class="check"><input type="checkbox" name="confirm" required>I understand this replaces the current journal.</label>`,async fd=>{const file=fd.get('file');if(!file||file.size>50*1024*1024)throw Error('Choose a backup file under 50 MB.');let backup;try{backup=JSON.parse(await file.text())}catch{throw Error('This is not valid JSON.')}if(backup.format!=='kinetic-backup'||backup.version!==1||!backup.data)throw Error('This is not a supported Kinetic backup.');let imported=backup.data,vault=C.vault;if(imported.encrypted){const result=await decryptState(imported,fd.get('passphrase'));imported=result.state;vault=result.vault}const validated=validateState(imported);await C.restore(validated,vault);toast('Backup restored and validated')});d.querySelector('[type=submit]').textContent='Validate & restore';return true}if(a==='export-csv'){exportCSV(C,id);return true}if(a==='refresh-offline'){await C.prepareOffline(true);toast(C.offlineStatus);C.render();return true}if(a==='install-app'){await C.installPrompt.prompt();C.installPrompt=null;C.render();return true}if(a==='reset-journal'){modal('Delete this device’s journal',`${field('confirm','Type DELETE to confirm','','text','required autocomplete="off"')}<p class="notice warning">This deletes every record and photo on this device. A downloaded backup can restore them. The current passphrase setting stays in place.</p>`,async fd=>{if(fd.get('confirm')!=='DELETE')throw Error('Type DELETE exactly.');await C.restore(initialState(),C.vault);toast('Journal reset')});return true}return false}
function exportCSV(C,type){const cell=v=>{let s=String(v??'');if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'},rows=type==='calories'?[['date','description','kcal','day_complete'],...C.state.calories.map(x=>[x.date,x.description,x.kcal,C.state.calorieDays.includes(x.date)])]:type==='weights'?[['date','weight_kg','note'],...C.state.weights.map(x=>[x.date,x.kg,x.note])]:type==='cardio'?[['date','activity','duration_min','distance_km','intensity','average_hr','met','note'],...C.state.cardio.map(x=>[x.date,x.type,x.duration,x.distance,x.intensity,x.hr,x.met,x.note])]:[['date','session','exercise_id','exercise','set','load_kg','reps','duration_sec','distance_m','RPE','RIR','warmup','complete','group','note'],...C.state.sessions.flatMap(s=>s.exercises.flatMap(e=>e.sets.map((x,i)=>[s.date,s.name,e.exerciseId,exercises.find(ex=>ex.id===e.exerciseId)?.name,i+1,x.load,x.reps,x.duration,x.distance,x.rpe,x.rir,x.warmup,x.done,e.superset,e.notes])))];download('kinetic-'+type+'-'+TODAY()+'.csv','\uFEFF'+rows.map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');toast('Readable CSV downloaded')}

